Biểu đồ hình quạt tròn dưới đây biểu diễn tần số tương đối của các ngôn ngữ lập trình được sử dụng khi viết $200$ phần mềm của một công ty công nghệ.

\choiceTF
{ Số phần mềm viết bằng ngôn ngữ JavaScript là $62$  }
   { \True  Số phần mềm viết bằng ngôn ngữ Ruby là $58$ }
     { \True Số phần mềm viết bằng ngôn ngữ  Go là $50$  }
    { Số phần mềm viết bằng ngôn ngữ C-Sharp là $50$  }
}{
\begin{tikzpicture}
    \def\R{2.6}
    \draw[double](0,0)circle(\R);
   \def\X{ 26 /north east lines/JavaScript/1,29/vertical lines/Ruby/2,25/dots/ Go/3,20/checkerboard/C-Sharp/4}
    \pgfmathsetmacro{\a}{90}
    \foreach \x/\mau/\yeuto/\stt [count=\i] in \X{
        \pgfmathsetmacro{\g}{\x/100*360};
        \pgfmathsetmacro{\b}{\a-\g};

        \fill[pattern=\mau,opacity=1,draw=black](0,0)--({\b+\g}:\R)arc({\b+\g}:\b:\R)--cycle;
        \path({\b+\g}:0.7*\R)arc({\b+\g}:\b:0.5*\R)node[pos=0.7,fill=white]{\textbf{\x $\%$}};

        \global \let \a = \b;
        \fill[pattern=\mau,draw=black] (3.5, 2.5-\stt) rectangle +(.575,.575);
        \path(6.3,2.75-\stt)node[yscale=1.25,xscale=1.25,text width=1.5*\R cm,align=left,scale=0.75]{\yeuto};
    };
    \path(3.5,3.5)node[yscale=1.5,xscale=1.5,text width=4*\R cm,align=center,scale=0.65]{\textbf{Tần số tương đối của các ngôn ngữ lập trình}};
\end{tikzpicture}
}
\loigiai{
a) \textbf{Sai}. Từ biểu đồ hình quạt tròn, JavaScript chiếm $26\% \Rightarrow$ số lượng là $200 \cdot 26\% = 52$ phần mềm.\\
b) \textbf{Đúng}. Từ biểu đồ hình quạt tròn, Ruby chiếm $29\% \Rightarrow$ số lượng là $200 \cdot 29\% = 58$ phần mềm.\\
c) \textbf{Đúng}. Từ biểu đồ hình quạt tròn, Go chiếm $25\% \Rightarrow$ số lượng là $200 \cdot 25\% = 50$ phần mềm.\\
d) \textbf{Sai}. Từ biểu đồ hình quạt tròn, C-Sharp chiếm $20\% \Rightarrow$ số lượng là $200 \cdot 20\% = 40$ phần mềm.
}\end{ex}

